/* ---------- Phrases balisées : {ÉTIQUETTE|texte} ; un groupe est mis en gras et l’élève en donne la nature, la fonction ou le sens ---------- */
const MK=/\{([A-Z0-9]+)\|([^}]+)\}/g;
const unmark=t=>t.replace(MK,(a,g,x)=>x);
function marked(tpls,L,o={}){
  return d=>{
    for(let k=0;k<25;k++){
      const t=P(tpls);const toks=[...t.matchAll(MK)].filter(m=>L[m[1]]);
      if(!toks.length)continue;
      const m=P(toks);const lab=L[m[1]];const good=lab.n;
      const s=t.replace(MK,(a,g,x,off)=>off===m.index?`<b>${x}</b>`:x);
      const pool=(lab.bad||Object.keys(L).filter(x=>x!==m[1])).map(x=>L[x]?L[x].n:x).filter(x=>x!==good);
      return ch(`${o.q||'Quelle est la nature de la proposition en gras ?'}<br>« ${s} »`,good,pickN([...new Set(pool)],3),{expl:`« ${m[2]} » : ${lab.e}`,hint:o.hint});
    }
    return ch(`${o.q||'Quelle est la nature de la proposition en gras ?'}<br>« ${unmark(tpls[0])} »`,'sujet',['COD'],{expl:'Observe le mot introducteur et ce que le groupe complète.'});
  };
}

